class ThreadPool {
public:
    explicit ThreadPool(size_t n) {
        for (size_t i = 0; i < n; ++i) workers_.emplace_back([this]{ worker_loop(); });
    }
    void submit(std::function<void()> task) {
        { std::lock_guard<std::mutex> lk(m_); tasks_.push(std::move(task)); }
        cv_.notify_one();
    }
    ~ThreadPool() {
        { std::lock_guard<std::mutex> lk(m_); stop_ = true; }
        cv_.notify_all();
        for (auto& w : workers_) w.join();
    }
private:
    void worker_loop() {
        while (true) {
            std::function<void()> task;
            { std::unique_lock<std::mutex> lk(m_);
              cv_.wait(lk, [this]{ return stop_ || !tasks_.empty(); });
              if (stop_ && tasks_.empty()) return;
              task = std::move(tasks_.front()); tasks_.pop(); }
            task();
        }
    }
    std::vector<std::thread> workers_;
    std::queue<std::function<void()>> tasks_;
    std::mutex m_; std::condition_variable cv_; bool stop_ = false;
};

